mapper.select:
/* master.mpst.selectAgingList*/ SELECT A.SITE, A.YYYYMM, C.TEXT1 AS SITE_NAME, A.CATEGORY_NAME, A.ITEM_NO, A.DESCRIPTION, A.SPECIFICATION, A.MAKER_NAME, A.UNIT_MEASURE, A.DEPT_NAME, A.WAREHOUSE_NAME, A.STOCK_QTY, A.STOCK_PRICE, A.STOCK_AMT, (A.D01_QTY+A.D02_QTY+A.D03_QTY) AS PRD_QTY_1, (A.D01_QTY+A.D02_QTY+A.D03_QTY) * A.STOCK_PRICE AS PRD_AMT_1, (A.D04_QTY+A.D05_QTY+A.D06_QTY) AS PRD_QTY_2, (A.D04_QTY+A.D05_QTY+A.D06_QTY) * A.STOCK_PRICE AS PRD_AMT_2, (A.D07_QTY+A.D08_QTY+A.D09_QTY +A.D10_QTY+A.D11_QTY+A.D12_QTY) AS PRD_QTY_3, (A.D07_QTY+A.D08_QTY+A.D09_QTY +A.D10_QTY+A.D11_QTY+A.D12_QTY) * A.STOCK_PRICE AS PRD_AMT_3, (A.D13_QTY+A.D14_QTY+A.D15_QTY +A.D16_QTY+A.D17_QTY+A.D18_QTY +A.D19_QTY+A.D20_QTY+A.D21_QTY +A.D22_QTY+A.D23_QTY+A.D24_QTY) AS PRD_QTY_4, (A.D13_QTY+A.D14_QTY+A.D15_QTY +A.D16_QTY+A.D17_QTY+A.D18_QTY +A.D19_QTY+A.D20_QTY+A.D21_QTY +A.D22_QTY+A.D23_QTY+A.D24_QTY) * A.STOCK_PRICE AS PRD_AMT_4, A.ETC_QTY AS PRD_QTY_5, A.ETC_QTY * A.STOCK_PRICE AS PRD_AMT_5 FROM KEP_STOCK_AGING A INNER JOIN ICOMCOD1 C ON (1 = 1 AND C.TYPE = 'SR01' AND C.CODE = A.SITE ) WHERE 1 = 1
AND A.SITE = #{st_site}
AND A.YYYYMM = #{st_yyyymm} AND A.ITEM_NO LIKE #{st_item_no} || '%'
